{"content": "#!/usr/bin/env python3
"""Verify encoded factor tables (TABLE_D1) against raw PDF page text."""
import re, os, sys
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import fitz
from factors import TABLE_D1

PDF = os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "inputs", "T_CSES_144-2024.pdf")
doc = fitz.open(PDF)

SECTORS = {"电力生产", "电力供应", "热力生产和供应", "采矿业和制造业"}

def parse_rows(pageno):
    """Parse 表D.1/E.7 rows from a page: returns list of (sector, fuel, tech, values8)."""
    t = doc[pageno].get_text()
    lines = [l.strip() for l in t.split("\n") if l.strip()]
    rows = []
    i = 0
    while i < len(lines):
        if lines[i] in SECTORS:
            # consume 11 lines: sector, fuel, tech, then 8 values
            if i + 10 < len(lines):
                fuel = lines[i+1].rstrip(" c")
                tech = lines[i+2].rstrip(" b")
                vals = lines[i+3:i+11]
                rows.append((lines[i], fuel, tech, vals))
                i += 11
                continue
        i += 1
    return rows

def norm_val(v):
    if v == "物料衡算":
        return "MB"
    if v.startswith("装机容量"):
        return "CAP"
    try:
        return float(v)
    except ValueError:
        return v

errors = 0
checked = 0
for pageno in (42, 43, 44, 53, 54):
    for (sector, fuel, tech, vals) in parse_rows(pageno):
        if sector == "电力供应":
            continue  # not needed for this run (no D4420 enterprises in candidates)
        key = (sector, fuel, tech)
        if key not in TABLE_D1:
            print(f"!! MISSING ENCODED ROW: {key} on page {pageno+1} vals={vals}")
            errors += 1
            continue
        enc = TABLE_D1[key]
        order = ["CO", "NOx", "SO2", "VOC", "PM25", "PM10", "BC", "OC"]
        for j, pol in enumerate(order):
            ev = norm_val(vals[j])
            cv = enc[pol]
            if isinstance(ev, float) and isinstance(cv, (int, float)):
                if abs(ev - cv) > 1e-9:
                    print(f"!! VALUE MISMATCH {key} {pol}: pdf={ev} encoded={cv}")
                    errors += 1
            elif ev != cv:
                print(f"!! VALUE MISMATCH {key} {pol}: pdf={ev} encoded={cv}")
                errors += 1
            checked += 1

# also check my encoded rows are all present in PDF (no extras)
pdf_keys = set()
for pageno in (42, 43, 44, 53, 54):
    for (sector, fuel, tech, vals) in parse_rows(pageno):
        if sector == "电力供应":
            continue
        pdf_keys.add((sector, fuel, tech))
for key in TABLE_D1:
    if key not in pdf_keys:
        print(f"!! ENCODED ROW NOT IN PDF: {key}")
        errors += 1

print(f"\nchecked {checked} cells; errors: {errors}; pdf rows: {len(pdf_keys)}; encoded rows: {len(TABLE_D1)}")
